actions.script:
tenant = null; canManage = false
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
boolean platformAdmin = ec.user.isInGroup('ADMIN')
if (!platformAdmin || !tenantId) {
    if (!activeOrg || activeOrg == '_NA_') return
    if (!platformAdmin) {
        def partyId = ec.user.userAccount?.partyId
        if (!partyId) return
        def info = ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo')
            .parameters([partyId:partyId]).disableAuthz().call()
        if (ec.message.hasError() || !(info?.userOrgIds ?: []).contains(activeOrg)) return
    }
}
def query = ec.entity.find('zenith.erp.saas.SaasTenant').disableAuthz()
if (tenantId) query.condition('tenantId', tenantId)
else query.condition('organizationPartyId', activeOrg)
def rows = query.limit(2).list()
if (rows.size() != 1) return // Ambiguous or missing billing ownership fails closed.
def candidate = rows[0]
if (!platformAdmin && candidate.organizationPartyId != activeOrg) return
tenant = candidate
canManage = platformAdmin || candidate.adminUserId == ec.user.userId || ec.user.isInGroup('ZENITH_ADMIN')
